def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    fg = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # The pattern is a rectangle defined by repeated foreground marks on
    # its horizontal and vertical sides. Accent missing side cells only.
    rows = [r for r in range(h) if sum(grid[r][c] == fg for c in range(w)) >= 3]
    cols = [c for c in range(w) if sum(grid[r][c] == fg for r in range(h)) >= 3]
    if len(rows) >= 2 and len(cols) >= 2:
        top, bottom = min(rows), max(rows)
        left, right = min(cols), max(cols)
        for c in range(left, right + 1):
            for r in (top, bottom):
                if grid[r][c] == bg:
                    out[r][c] = 2
        for r in range(top, bottom + 1):
            for c in (left, right):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
